<script setup>
import { ref, computed, inject, onMounted, watch } from 'vue'
import TemplateDialog from '../components/TemplateDialog.vue'
import StatusChip from '../components/StatusChip.vue'
import { selectionMatchesSearch } from '../services/surgery-selection'
import { phases } from '../services/repository'
const repo=inject('repository'),notify=inject('notify'),catalog=ref(null),error=ref(''),loadError=ref(''),busy=ref(false),loading=ref(true),templateOpen=ref(false),editing=ref(null),page=ref(1),lastReport=ref(null)
const form=ref({templateId:null,surgeryId:null,occurredAt:'',notes:''})
const surgerySearch=ref('')
watch(surgerySearch,query=>{const selected=surgeries.value.find(s=>s.value===form.value.surgeryId);if(form.value.surgeryId&&!selectionMatchesSearch(selected,query))form.value.surgeryId=null})
const maxTime=()=>new Date(Date.now()+8*3600000).toISOString().slice(0,16)
const enabled=computed(()=>catalog.value?.templates.filter(t=>t.enabled)||[])
const selected=computed(()=>catalog.value?.templates.find(t=>t.id===form.value.templateId))
const surgeries=computed(()=>catalog.value?.surgeries.filter(s=>s.status!=='取消').map(s=>({value:s.id,title:[s.patientName,s.surgeryNo,s.department,s.surgeryName].join(' · ')}))||[])
const history=computed(()=>catalog.value?.reports.slice((page.value-1)*10,page.value*10)||[])
async function load(){loadError.value='';try{catalog.value=await repo.getCatalog()}catch(e){loadError.value=e.message}finally{loading.value=false}}
function edit(t){editing.value=t||null;templateOpen.value=true}
async function saved(){await load();notify('事件模板已保存')}
async function submit(){busy.value=true;error.value='';lastReport.value=null;try{if(!selectionMatchesSearch(surgeries.value.find(s=>s.value===form.value.surgeryId),surgerySearch.value))throw Error('请选择与搜索条件匹配的具体手术');const r=await repo.submitReport(form.value);lastReport.value=r;await load();page.value=1;notify('事件已上报，并加入告警中心');form.value={templateId:null,surgeryId:null,occurredAt:'',notes:''}}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template>
<div class="page-heading"><div><h1>告警事件填报</h1><p>系统无法自动采集时，选择事件模板、具体手术及发生时间快速上报。</p></div><VBtn prepend-icon="tabler-plus" @click="edit()" :disabled="!!loadError">新建事件模板</VBtn></div>
<VAlert v-if="loadError" type="error" variant="tonal" class="mb-6">{{loadError}}<VBtn variant="text" @click="load">重试读取</VBtn></VAlert><VProgressLinear v-if="loading" indeterminate class="mb-6"/>
<VAlert variant="tonal" color="primary" icon="tabler-info-circle" class="mb-6"><span class="caption">本机演示：模板与填报记录保存在此浏览器。通知角色会进入告警记录，尚未连接实际消息服务。</span></VAlert>
<VAlert v-if="lastReport" type="success" variant="tonal" class="mb-6" role="status">事件上报成功：{{lastReport.indicator}}<VBtn variant="text" :to="'/alerts/'+lastReport.id">查看告警详情</VBtn></VAlert>
<div class="report-layout">
<VCard title="快速上报"><VCardText><p class="caption muted mb-6">带 * 的项目为必填项。时间统一使用北京时间。</p><form @submit.prevent="submit"><VAlert v-if="error" type="error" variant="tonal" class="mb-5" role="alert">{{error}}</VAlert><div class="field"><label>事件模板 *</label><VSelect aria-label="事件模板" v-model="form.templateId" :items="enabled.map(t=>({value:t.id,title:t.name}))" placeholder="请选择已启用的事件模板" :disabled="!enabled.length" no-data-text="暂无启用模板"/></div><div class="preview-box" v-if="selected"><div class="action-row mb-2"><StatusChip :value="selected.level"/><span>{{phases[selected.phase]}}</span></div><p>通知：{{selected.recipients.join('、')}}</p><p class="caption muted">{{selected.description||'未设置填报说明'}}</p></div><div class="preview-box" v-else><p>{{enabled.length?'选择模板后，将显示告警等级、发生阶段和通知角色。':'暂无启用模板，请先新建事件模板。'}}</p><VBtn v-if="!enabled.length" variant="text" size="small" class="mt-2" @click="edit()">新建事件模板</VBtn></div>
<div class="field"><label>具体手术 *</label><VAutocomplete aria-label="具体手术" v-model:search="surgerySearch" :custom-filter="(value,query)=>String(value).toLowerCase().includes(String(query||'').trim().toLowerCase())" v-model="form.surgeryId" :items="surgeries" placeholder="搜索患者姓名、手术编号、科室或术式" no-data-text="未找到匹配手术" clearable/></div><div class="field"><label for="occurred-at">事件发生时间 *</label><VTextField id="occurred-at" v-model="form.occurredAt" type="datetime-local" :max="maxTime()"/><p class="caption muted mt-2">填写真实的事件发生时间，不能晚于当前时间。</p></div><div class="field"><label for="notes">补充说明（选填）</label><VTextarea id="notes" v-model="form.notes" rows="4" maxlength="1000" counter="1000" placeholder="补充现场情况、原始依据或已采取的措施"/></div><VDivider class="mb-5"/><div class="action-row"><VBtn type="submit" prepend-icon="tabler-send" :loading="busy" :disabled="!enabled.length||!!loadError">提交上报</VBtn><span class="caption muted">提交后自动进入告警中心</span></div></form></VCardText></VCard>
<VCard><div class="section-head"><div><h2>事件模板</h2><p>维护事件定义，统一填报口径。</p></div><VChip variant="tonal" color="primary" label>{{catalog?.templates.length||0}} 项</VChip></div><VCardText><div v-if="!catalog?.templates.length" class="empty"><VAvatar color="primary" variant="tonal" rounded size="56"><VIcon icon="tabler-files" size="30"/></VAvatar><h3>建立第一个事件模板</h3><p>定义发生阶段、告警等级与通知角色，<br>即可开始人工填报。</p><VBtn variant="tonal" @click="edit()" :disabled="!!loadError">新建事件模板</VBtn></div><article v-for="t in catalog?.templates" :key="t.id" class="template-item"><div class="template-title"><strong>{{t.name}}</strong><VChip :color="t.enabled?'success':'secondary'" variant="tonal" label>{{t.enabled?'已启用':'未启用'}}</VChip></div><div class="action-row mt-3"><StatusChip :value="t.level"/><span class="caption">{{phases[t.phase]}}</span></div><p>通知：{{t.recipients.join('、')}}</p><p>{{t.description||'未设置填报说明'}}</p><VBtn variant="text" size="small" prepend-icon="tabler-edit" @click="edit(t)">编辑模板</VBtn></article></VCardText></VCard>
</div>
<VCard class="mt-6"><div class="section-head"><div><h2>人工填报记录</h2><p>保留填报时的模板快照，可从详情追溯。</p></div><span class="caption muted">共 {{catalog?.reports.length||0}} 条</span></div><VTable><thead><tr><th>发生时间</th><th>事件 / 等级</th><th>患者 / 手术</th><th>通知角色</th><th>操作</th></tr></thead><tbody><tr v-for="r in history" :key="r.id"><td class="date-cell">{{r.triggerTime}}</td><td>{{r.indicator}}<div class="mt-2"><StatusChip :value="r.level"/></div></td><td>{{r.patientName}}<span class="subline">{{r.surgeryName}} · {{r.surgeryNo}}</span></td><td>{{r.recipients.join('、')}}</td><td><VBtn :to="'/alerts/'+r.id" variant="text" size="small">查看详情</VBtn></td></tr></tbody></VTable><div v-if="!history.length" class="empty"><VIcon icon="tabler-clipboard-text" color="secondary" size="32"/><h3>暂无人工填报记录</h3><p>提交上报后，记录将显示在这里。</p></div><div class="pagination-row"><span>第 {{page}} / {{Math.max(1,Math.ceil((catalog?.reports.length||0)/10))}} 页</span><VPagination v-model="page" :length="Math.max(1,Math.ceil((catalog?.reports.length||0)/10))" :total-visible="5" size="small"/></div></VCard>
<TemplateDialog v-model="templateOpen" :template="editing" :roles="catalog?.roles||[]" @saved="saved"/>
</template>
